import 'package:flutter/material.dart';
class PrivacyDialog extends StatelessWidget {const PrivacyDialog({super.key});@override Widget build(BuildContext context)=>AlertDialog(title:const Text('Location tracking policy'),content:const SingleChildScrollView(child:Text('Location is collected only during an active work session. Tracking can continue while the app is backgrounded or the screen is off, and Android keeps a persistent “Location tracking active” notification visible. Tracking stops when you End Day, sign out, the device is revoked, or your company disables GPS. Location points may be retained according to your employer policy and upload when a connection is available.')),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Not now')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('I understand and agree'))]);}
